 const [resetToken]=useState(()=>new URLSearchParams(window.location.search).get('reset_token')||'');const [paymentMethod,setPaymentMethod]=useState<'cash'|'bank_transfer'>('cash');const [replyDraft,setReplyDraft]=useState<Record<number,string>>({});const [myRequests,setMyRequests]=useState<{id:number;question:string;status:string;reply_text?:string}[]>([]);
