 const [petId,setPetId]=useState(0),[service,setService]=useState(()=>{const n=sessionStorage.getItem('petday_service_prefill')||'Grooming toàn diện';sessionStorage.removeItem('petday_service_prefill');return hasBookableService(n)?n:'Grooming toàn diện'}),[branch,setBranch]=useState('PetDay Thảo Điền'),[date,setDate]=useState(tomorrow),[slot,setSlot]=useState('08:30'),[step,setStep]=useState(1);
