 async function reload(t=token){
  if(!t)return;
  // Authenticate independently of optional business tables: never discard a valid login because a migration is missing.
  const u=await api('/me','GET',undefined,t);
  setUser({id:u.id,email:u.email,fullName:u.full_name,role:u.role});setProfileName(u.full_name);if(u.role==='admin')api('/admin/overview','GET',undefined,t).then(setAdminOverview).catch(()=>{});
  const [pResult,bResult]=await Promise.allSettled([api('/pets','GET',undefined,t),api('/bookings','GET',undefined,t)]);
  if(pResult.status==='fulfilled'){const p=pResult.value;setPets(p);if(p.length)setPetId(prev=>p.some((v:Pet)=>v.id===prev)?prev:p[0].id)}
  else{setPets([]);setError('Không tải được hồ sơ thú cưng: '+String(pResult.reason?.message||pResult.reason));}
  if(bResult.status==='fulfilled'){setBookings(bResult.value);if(pResult.status==='fulfilled')setError('');}
  else{setBookings([]);setError('Không tải được lịch hẹn: '+String(bResult.reason?.message||bResult.reason)+'. Kiểm tra SQL migration.');}
  if(u.role==='customer'||u.role==='admin')api('/cancellation-requests','GET',undefined,t).then(setCancellations).catch(()=>{});
  if(u.role==='customer'){api('/my/refunds','GET',undefined,t).then(setRefunds).catch(()=>{});api('/my/consultations','GET',undefined,t).then(setMyRequests).catch(()=>{});api('/my/notifications','GET',undefined,t).then(setNotifications).catch(()=>{});}
  if(u.role==='admin'){api('/admin/refunds','GET',undefined,t).then(setRefunds).catch(()=>{});api('/admin/finance/summary','GET',undefined,t).then(setFinance).catch(()=>{});api('/admin/payment-settings','GET',undefined,t).then(v=>{if(v.bankTransfer)setBankDraft(v.bankTransfer)}).catch(()=>{});api('/admin/promotions','GET',undefined,t).then(setPromotions).catch(()=>{});api('/admin/payments/audit','GET',undefined,t).then(setPaymentAudit).catch(()=>{});}
}
 useEffect(()=>{if(token)reload(token).catch(()=>{sessionStorage.removeItem('petday_token_v3');sessionStorage.removeItem('petday_api_token');setToken('');setUser(null);}).finally(()=>setLoading(false));},[]);
 useEffect(()=>{if(resetToken){const u=new URL(window.location.href);u.searchParams.delete('reset_token');window.history.replaceState(null,'',u.pathname+(u.search||'')+u.hash);}},[resetToken]);
 // Additional-service flow: pick a second package, but create a second independently verified booking.
 useEffect(()=>{
  if(view!=='booking'||!pets.length)return;
  const raw=sessionStorage.getItem('petday_additional_service_draft');if(!raw)return;
  sessionStorage.removeItem('petday_additional_service_draft');
  try{const b=JSON.parse(raw);if(!pets.some(p=>p.id===b.petId))return;
   setPetId(b.petId);setService('Grooming cơ bản');setBranch(b.branch);
   setDate(typeof b.date==='string'&&b.date>=tomorrow()?b.date:tomorrow());
   setSlot('08:30');setStep(2);setRetailChosen([]);setSelectedAddOns([]);
   setPromoCode('');setPromoPreview(null);setPaymentMethod('cash');setTaxiEnabled(false);
  }catch{}
 },[view,pets]);
 // Restore requested rebooking after navigation even when Portal remounts between routes.
 useEffect(()=>{
  if(view!=='booking'||!pets.length)return;
  const draft=sessionStorage.getItem('petday_rebook_draft');if(!draft)return;
  sessionStorage.removeItem('petday_rebook_draft');
  try{const b=JSON.parse(draft);
   if(!pets.some(p=>p.id===b.petId))return;
   if(!hasBookableService(b.service))return;
   setPetId(b.petId);setService(b.service);setBranch(b.branch);
   setDate(tomorrow());setSlot('08:30');setStep(2);setSelectedAddOns([]);setRetailChosen([]);
   setPromoCode('');setPromoPreview(null);setPaymentMethod('cash');setTaxiEnabled(false);setTaxiAddress('');setTaxiPhone('');
  }catch{ /* Malformed saved draft is ignored. */ }
 },[view,pets]);
 useEffect(()=>{setAvailability(null)},[petId,service,branch,date,slot]);
 useEffect(()=>{
  if(view!=='booking'||step!==3||!token)return;
  let cancelled=false;
  setDayLoading(true);setDayError('');setDayAvailability([]);
  api('/availability/day?'+new URLSearchParams({branch,date,service}),'GET',undefined,token)
   .then(result=>{if(!cancelled)setDayAvailability(result.slots||[]);})
   .catch(err=>{if(!cancelled)setDayError(err instanceof Error?err.message:'Không tải được khung giờ.');})
   .finally(()=>{if(!cancelled)setDayLoading(false);});
  return ()=>{cancelled=true};
 },[view,step,token,branch,date,service]);
 useEffect(()=>{
  if(view!=='booking'||step!==3||!dayAvailability.length)return;
  if(!dayAvailability.some(x=>x.slot===slot&&x.available)){
   const first=dayAvailability.find(x=>x.available);
   if(first)setSlot(first.slot);
  }
 },[view,step,dayAvailability,slot]);
 
 useEffect(()=>{setPromoPreview(null)},[petId,service,selectedAddOns,taxiEnabled,taxiZone,retailChosen]);
 useEffect(()=>{const item=servicePackages.find(x=>x.name===service);if(item&&item.category!==serviceCategory)setServiceCategory(item.category as 'Grooming'|'Spa'|'Daycare');},[service]);
 useEffect(()=>{if(token)api('/retail/products','GET',undefined,token).then(setRetailProducts).catch(()=>setRetailProducts([]))},[token]);
 useEffect(()=>{api('/payment/options').then(setPayOptions).catch(()=>{});api('/catalog', 'GET',undefined,token).then(x=>{setAddOnCatalog(x.addOns||{});setLiveServicePrices(Object.fromEntries(Object.entries(x.services||{}).map(([n,v]:any)=>[n,Number(v.base||0)])));setActiveServiceNames(Object.keys(x.services||{}))}).catch(()=>{});},[token]);
 useEffect(()=>{if(!token||!petId){setQuote(null);return;}let cancelled=false;api('/quote?'+new URLSearchParams({petId:String(petId),service,addOns:selectedAddOns.join(','),taxiZone:taxiEnabled?taxiZone:'none',retail:JSON.stringify(retailChosen)}),'GET',undefined,token).then(q=>{if(!cancelled)setQuote(q)}).catch(()=>{if(!cancelled)setQuote(null)});return()=>{cancelled=true};},[token,petId,service,selectedAddOns,taxiEnabled,taxiZone,retailChosen]);
 const run=async(fn:()=>Promise<void>)=>{setBusy(true);setError('');setNotice('');try{await fn()}catch(e){setError(e instanceof Error?e.message:'Có lỗi xảy ra')}finally{setBusy(false)}};
 async function saveBank(){await run(async()=>{const result=await api('/admin/payment-settings','PUT',bankDraft,token);setBankDraft(result.bankTransfer);setPayOptions(await api('/payment/options'));setNotice('Đã lưu tài khoản nhận chuyển khoản. Khách có thể chọn phương thức chuyển khoản cho lịch mới.');});}
 async function changePassword(){await run(async()=>{if(passwordNew!==passwordConfirm)throw Error('Mật khẩu mới xác nhận chưa khớp.');if(passwordNew.length<8)throw Error('Mật khẩu mới tối thiểu 8 ký tự.');const r=await api('/me/change-password','POST',{currentPassword:passwordCurrent,newPassword:passwordNew},token);setPasswordCurrent('');setPasswordNew('');setPasswordConfirm('');setNotice(r.message);});}
 async function changeBookingPayment(code:string,paymentMethod:'cash'|'bank_transfer'){await run(async()=>{await api(`/bookings/${code}/payment-method`,'PATCH',{paymentMethod},token);await reload();setNotice('Đã cập nhật phương thức thanh toán cho '+code);});}
 async function saveProfile(){await run(async()=>{const u=await api('/me','PATCH',{fullName:profileName},token);setUser({id:u.id,email:u.email,fullName:u.full_name,role:u.role});setNotice('Đã cập nhật thông tin cá nhân.');});}
 function logout(){sessionStorage.removeItem('petday_token_v3');sessionStorage.removeItem('petday_api_token');setToken('');setUser(null);setPets([]);setBookings([]);onGo('home');}
 async function submitAuth(){await run(async()=>{if(authMode==='forgot'){try{const out=await api('/auth/forgot-password','POST',{email});setNotice(out.message);}catch(e){if(String(e).includes('503'))throw Error('Email khôi phục chưa gửi được. Cần cấu hình SMTP trong server/.env và khởi động lại backend; xem /api/health/features.');throw e;}return;}if(authMode==='reset'){if(!resetToken)throw Error('Liên kết đặt lại mật khẩu không hợp lệ. Hãy yêu cầu liên kết mới.');if(password!==resetConfirm)throw Error('Hai lần nhập mật khẩu mới chưa khớp.');const out=await api('/auth/reset-password','POST',{token:resetToken,password});window.history.replaceState(null,'',window.location.pathname+window.location.hash);setAuthMode('login');setPassword('');setNotice(out.message);return;}if(authMode==='register')await api('/auth/register','POST',{fullName,email,password});const result=await api('/auth/login','POST',{email,password});sessionStorage.setItem('petday_token_v3',result.token);setToken(result.token);await reload(result.token);setPassword('');setNotice('Đã xác thực tài khoản.');if(result.user?.role==='staff')onGo('admin');});}
 function editPet(p:Pet){setEditingPet(p.id);setName(p.name);setSpecies(p.species);setBreed(p.breed||'');setGender(p.gender||'Chưa xác định');setAge(String(p.age));setWeight(String(p.weight));setNotes(p.notes||'');setPhotoUrl(p.photoUrl||'');}
 function clearPetForm(){setEditingPet(null);setName('');setSpecies('Chó');setBreed('');setGender('Chưa xác định');setAge('');setWeight('');setNotes('');setPhotoUrl('');}
 async function uploadPhoto(file:File){setError('');setNotice('');if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){setError('Chỉ chấp nhận JPG, PNG, WebP tối đa 5 MB.');return;}if(!token){setError('Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại để tải ảnh.');return;}setUploading(true);try{const r=await fetch('/api/pets/photo',{method:'POST',headers:{'Content-Type':file.type,Authorization:`Bearer ${token}`},body:file});const out=await r.json().catch(()=>({error:'Server trả về phản hồi không đúng định dạng JSON. Kiểm tra proxy /api và terminal backend.'}));if(!r.ok)throw Error((out.error||'Không tải được ảnh')+' [HTTP '+r.status+']');if(!out.url||!/^\/uploads\/[a-f0-9-]+\.(jpg|png|webp)$/.test(out.url))throw Error('Đường dẫn ảnh trả về không hợp lệ.');setPhotoUrl(out.url);setNotice('Đã tải ảnh lên thành công. Bấm '+(editingPet?'“Lưu thay đổi”':'“Thêm thú cưng”')+' để gắn ảnh vào hồ sơ.');}catch(e){setError('Tải ảnh thất bại: '+(e instanceof Error?e.message:'Không thể kết nối API')+'. Nếu lỗi tiếp diễn, xem Network → /api/pets/photo.')}finally{setUploading(false)}}
 async function deletePet(p:Pet){
  const hasHistory=bookings.some(b=>b.petId===p.id);
  const action=hasHistory?'lưu trữ':'xóa';
  if(!window.confirm(`${hasHistory?'Lưu trữ':'Xóa'} hồ sơ ${p.name}? ${hasHistory?'Hồ sơ sẽ ẩn khỏi danh sách đặt lịch, nhưng lịch sử vẫn được bảo toàn.':'Hồ sơ chưa có lịch sử sẽ được xóa vĩnh viễn.'}`))return;
  await run(async()=>{
   await api(`/pets/${p.id}${hasHistory?'/archive':''}`,hasHistory?'PATCH':'DELETE',undefined,token);
   if(editingPet===p.id)clearPetForm();
   if(petId===p.id)setPetId(0);
   await reload();setNotice(`Đã ${action} hồ sơ ${p.name}.`);
  });
 }
 async function addPet(){await run(async()=>{const payload={name,species,breed,gender,age:Number(age),weight:Number(weight),notes,photoUrl};await api(editingPet?`/pets/${editingPet}`:'/pets',editingPet?'PUT':'POST',payload,token);await reload();clearPetForm();setNotice(editingPet?'Đã cập nhật hồ sơ thú cưng.':'Đã tạo hồ sơ thú cưng.');});}
 async function checkAvailability(){await run(async()=>{const r=await api('/availability?'+new URLSearchParams({branch,date,slot,service}), 'GET',undefined,token);setAvailability(r);if(!r.available)throw Error(r.reason||'Khung giờ này đã hết chỗ. Vui lòng chọn khung giờ khác.');setStep(4);});}
 async function verifyPromotion(){await run(async()=>{if(!petId)throw Error('Chọn thú cưng trước khi kiểm tra ưu đãi.');const r=await api('/promotions/verify?'+new URLSearchParams({code:promoCode,petId:String(petId),service,addOns:selectedAddOns.join(','),taxiZone:taxiEnabled?taxiZone:'none',retail:JSON.stringify(retailChosen)}),'GET',undefined,token);setPromoPreview(r);setNotice('Đã áp dụng mã ưu đãi dự kiến. Hệ thống sẽ xác minh lại khi đặt lịch.');});}
 async function book(){await run(async()=>{if(promoCode.trim()&&!promoPreview)throw Error('Vui lòng bấm Áp dụng để kiểm tra mã ưu đãi trước khi đặt lịch.');if(paymentMethod==='bank_transfer'&&!payOptions?.bankTransfer?.enabled)throw Error('Chưa cấu hình tài khoản nhận chuyển khoản.');const r=await api('/bookings','POST',{petId,service,branch,date,slot,addOns:selectedAddOns,retail:retailChosen,taxi:taxiEnabled?{enabled:true,zone:taxiZone,address:taxiAddress,phone:taxiPhone}:undefined,paymentMethod,promoCode:promoPreview?.code===promoCode.trim().toUpperCase()?promoPreview.code:'',idempotencyKey:crypto.randomUUID()},token);await reload();setNotice(paymentMethod==='bank_transfer'?`Đã tạo lịch ${r.code}. Vui lòng nhập thông tin chuyển khoản để Admin xác nhận.`:`Đã nhận yêu cầu đặt lịch ${r.code}. Vui lòng chờ xác nhận.`);if(paymentMethod==='bank_transfer'){sessionStorage.setItem('petday_payment_focus_booking',String(r.code));setCustomerTab('payments');}setStep(1);setSelectedAddOns([]);setRetailChosen([]);setTaxiEnabled(false);setTaxiAddress('');setTaxiPhone('');onGo('appointments');});}
 async function loadReschedules(){await run(async()=>{setReschedules(await api('/reschedule-requests','GET',undefined,token));});}
 async function requestReschedule(code:string){await run(async()=>{await api(`/bookings/${code}/reschedule`,'POST',{date:newDates[code],slot:newSlots[code]||'08:30',reason:changeReasons[code]||''},token);setReschedules(await api('/reschedule-requests','GET',undefined,token));setNotice('Yêu cầu đổi lịch đã gửi. Lịch cũ vẫn giữ nguyên cho đến khi được duyệt.');});}
 async function decideReschedule(id:number,decision:'approved'|'rejected'){await run(async()=>{await api(`/admin/reschedule-requests/${id}`,'PATCH',{decision},token);setReschedules(await api('/reschedule-requests','GET',undefined,token));await reload();setNotice('Đã xử lý yêu cầu đổi lịch.');});}
 async function askCancellation(code:string){await run(async()=>{const reason=(cancelReasons[code]||'').trim();if(reason.length<10)throw Error('Vui lòng nhập lý do hủy tối thiểu 10 ký tự.');await api('/bookings/'+encodeURIComponent(code)+'/cancellation-request','POST',{reason},token);setCancellations(await api('/cancellation-requests','GET',undefined,token));setCancelReasons(x=>({...x,[code]:''}));setNotice('Đã gửi yêu cầu hủy. Lịch vẫn giữ nguyên cho tới khi Admin chấp thuận.');});}
 async function resolveCancellation(id:number,decision:'approved'|'rejected'){
  const note=(cancelNotes[id]||'').trim();
  if(note.length<8){setCancelActionErrors(v=>({...v,[id]:'Cần ghi rõ lý do xử lý (ít nhất 8 ký tự).'}));return;}
  if(decision==='approved'&&!window.confirm('Chấp thuận hủy lịch? Nếu lịch đã thanh toán, PetDay sẽ tạo hồ sơ CHỜ hoàn tiền; không tự chuyển tiền.'))return;
  setBusy(true);setError('');setNotice('');setCancelActionErrors(v=>({...v,[id]:''}));
  try{
   await api('/admin/cancellation-requests/'+id,'PATCH',{decision,note},token);
   // Remove the successfully processed request locally, even if an unrelated
   // optional dashboard API fails while refreshing.
   setCancellations(rows=>rows.map(r=>String(r.id)===String(id)?{...r,status:decision,adminNote:note}:r));
   setNotice(decision==='approved'?'Đã duyệt hủy lịch. Nếu đã thu tiền, kiểm tra hồ sơ hoàn tiền trong Tài chính.':'Đã từ chối yêu cầu hủy và lưu lý do.');
   await reload().catch(e=>setError('Đã xử lý yêu cầu, nhưng cập nhật dữ liệu gặp lỗi: '+String(e?.message||e)));
  }catch(e){
   setCancelActionErrors(v=>({...v,[id]:'Không lưu được quyết định hủy: '+(e instanceof Error?e.message:'Lỗi kết nối Backend')+'. Trạng thái chưa thay đổi.'}));
  }finally{setBusy(false);}
 }
 async function requestRefund(code:string){await run(async()=>{const reason=(refundReasons[code]||'').trim();if(reason.length<10)throw Error('Vui lòng mô tả lý do ít nhất 10 ký tự.');await api('/bookings/'+encodeURIComponent(code)+'/refund-request','POST',{reason},token);setRefunds(await api('/my/refunds','GET',undefined,token));setRefundReasons(v=>({...v,[code]:''}));setNotice('Đã gửi yêu cầu. Nhân viên sẽ kiểm tra và phản hồi trong tài khoản.');});}
 async function decideRefund(id:number,decision:'approve'|'reject'|'complete'){await run(async()=>{const note=(refundNotes[id]||'').trim(),reference=(refundRefs[id]||'').trim();if(decision==='reject'&&note.length<8)throw Error('Nhập lý do từ chối ít nhất 8 ký tự.');const refund=refunds.find(x=>x.id===id);const amountText=(refundAmounts[id]||'').trim();const amount=amountText?Number(amountText):Number(refund?.amount);if(decision==='approve'&&(!Number.isSafeInteger(amount)||amount<=0||amount>Number(refund?.total)))throw Error('Số tiền hoàn không hợp lệ hoặc vượt quá tiền đã thu.');if(decision==='approve'&&amount<Number(refund?.total)&&note.length<8)throw Error('Hoàn một phần cần ghi rõ lý do ít nhất 8 ký tự.');if(decision==='complete'&&reference.length<4)throw Error('Cần mã tham chiếu hoàn tiền thực tế hoặc số phiếu thu/chi.');if(decision==='complete'&&!window.confirm('Xác nhận tiền đã HOÀN thực tế cho khách? Thao tác này sẽ cập nhật sổ đối soát.'))return;await api('/admin/refunds/'+id,'PATCH',{decision,note,...(decision==='complete'?{reference}:decision==='approve'?{amount}:{})},token);await reload();setNotice(decision==='complete'?'Đã ghi nhận xử lý hoàn tiền và lưu mã đối soát.':decision==='approve'?'Đã duyệt hoàn tiền. Chỉ xác nhận hoàn tất sau khi thực hiện hoàn tiền.':'Đã từ chối yêu cầu hoàn tiền và gửi lý do cho khách.');});}
 async function recordPayment(code:string,method:string,paymentStatus:'Chưa thanh toán'|'Đã thanh toán'){
  await run(async()=>{if(paymentStatus==='Đã thanh toán'&&method==='bank_transfer'&&!paymentRefs[code]?.trim())throw Error('Cần nhập mã giao dịch ngân hàng đã đối soát.');
  if(paymentStatus==='Chưa thanh toán'&&!paymentNotes[code]?.trim())throw Error('Nhập lý do điều chỉnh trạng thái thanh toán.');
  await api(`/admin/bookings/${code}/payment`,'PATCH',{paymentStatus,reference:paymentRefs[code]||'',note:paymentNotes[code]||''},token);
  await reload();setNotice('Đã cập nhật thanh toán và lưu nhật ký đối soát.');});
 }
 async function refreshPromos(){setPromotions(await api('/admin/promotions','GET',undefined,token));}
 async function createPromo(){await run(async()=>{const payload={...newPromo,discountValue:Number(newPromo.discountValue),minOrder:Number(newPromo.minOrder),maxPerCustomer:Number(newPromo.maxPerCustomer),startsAt:new Date(newPromo.startsAt).toISOString(),endsAt:new Date(newPromo.endsAt).toISOString()};await api('/admin/promotions','POST',payload,token);await refreshPromos();setNewPromo(v=>({...v,code:''}));setNotice('Đã tạo mã ưu đãi.');});}
