 async function sendReminders(){await run(async()=>{const r=await api('/admin/reminders/send','POST',{},token);setReminderPreview(await api('/admin/reminders/preview','GET',undefined,token));setNotice(`Đã tạo ${r.sent} thông báo nhắc lịch trong tài khoản khách. Không gửi SMS hoặc email.`);});}
 async function postMilestone(code:string,eventType:'check_in'|'care_update'|'ready'|'check_out'){
  const note=(milestoneNotes[code]||'').trim();if(note.length>1200){setError('Ghi chú chăm sóc tối đa 1200 ký tự.');return;}
  await run(async()=>{await api('/admin/bookings/'+encodeURIComponent(code)+'/milestone','POST',{eventType,note},token);
   const result=await api('/bookings/'+encodeURIComponent(code)+'/timeline','GET',undefined,token);
   setTimelineData(x=>({...x,[code]:result.events}));setTimelineOpen(code);setMilestoneNotes(x=>({...x,[code]:''}));await reload();setNotice('Đã lưu mốc chăm sóc vào PostgreSQL và tạo thông báo cho khách.');});
 }
 async function markNoShow(code:string){
  const booking=bookings.find(b=>b.code===code);
  if(!booking){setError('Không tìm thấy lịch hẹn để xử lý.');return;}
  const reason=(noShowNotes[code]||'').trim();
  if(reason.length<8){setError('Vui lòng nhập lý do khách không đến ít nhất 8 ký tự ngay trong thẻ lịch.');return;}
  if(!window.confirm('Đóng lịch '+code+' do khách không đến? Có thể thực hiện trước giờ hẹn theo quyết định của Admin. Khách sẽ được thông báo; thanh toán không thay đổi.'))return;
  await run(async()=>{await api('/admin/bookings/'+encodeURIComponent(code)+'/no-show','POST',{reason},token);await reload();setNoShowNotes(v=>({...v,[code]:''}));setNotice('Đã đóng lịch do khách không đến. Lịch chuyển Đã hủy, yêu cầu hủy đang chờ (nếu có) được xử lý và khách được thông báo.');});
 }
 function bookAgain(b:Booking){
  if(!b.petId||!pets.some(p=>p.id===Number(b.petId))){setError('Hồ sơ thú cưng không còn khả dụng. Hãy chọn thú cưng trong trang đặt lịch.');onGo('booking');return;}
  sessionStorage.setItem('petday_rebook_draft',JSON.stringify({petId:Number(b.petId),service:b.service,branch:b.branch}));
  setPetId(Number(b.petId));setService(b.service);setBranch(b.branch);
  // Always recheck future availability, quote, discounts and method; never copy the old payment status.
  setDate(tomorrow());setSlot('08:30');setStep(2);setSelectedAddOns([]);
  setPromoCode('');setPromoPreview(null);setPaymentMethod('cash');setTaxiEnabled(false);setTaxiAddress('');setTaxiPhone('');setAvailability(null);
  onGo('booking');
 }
 // Book another service for the same pet as a separate appointment.
 // Use the full existing booking wizard so capacity, price and payment are independently verified.
 function bookAdditionalService(b:Booking){
  if(!b.petId||!pets.some(p=>p.id===Number(b.petId))){setError('Hồ sơ thú cưng không còn khả dụng.');return;}
  const draft={petId:Number(b.petId),service:'Grooming cơ bản',branch:b.branch,date:b.date};
  sessionStorage.setItem('petday_additional_service_draft',JSON.stringify(draft));
  setPetId(draft.petId);setService(draft.service);setBranch(draft.branch);
  setDate(b.date>=tomorrow()?b.date:tomorrow());setSlot('08:30');setStep(2);
  setSelectedAddOns([]);setRetailChosen([]);setPromoCode('');setPromoPreview(null);
  setPaymentMethod('cash');setTaxiEnabled(false);setTaxiAddress('');setTaxiPhone('');setAvailability(null);
  onGo('booking');
 }
