 useEffect(()=>{const focus=()=>{const target=sessionStorage.getItem('petday_focus_section');if(!target)return;
  if(view==='admin'&&user?.role==='admin'){
   const map:Record<string,typeof adminTab>={'admin-bookings':'appointments','admin-reschedules':'appointments','admin-consultations':'support','admin-refunds':'finance','admin-staff':'staff','admin-overview-kpis':'today'};
   if(map[target]){setAdminTab(map[target]);sessionStorage.removeItem('petday_focus_section');return;}
  }if(view==='appointments'&&user?.role==='customer'){const tabs:Record<string,typeof customerTab>={'appointments-list':'schedule','customer-payments':'payments','customer-refunds':'refunds','customer-reviews':'reviews'};if(tabs[target]){setCustomerTab(tabs[target]);sessionStorage.removeItem('petday_focus_section');window.scrollTo({top:160,behavior:'smooth'});return;}}const element=document.getElementById(target);if(element){sessionStorage.removeItem('petday_focus_section');setTimeout(()=>element.scrollIntoView({behavior:'smooth',block:'start'}),80);}};const id=setTimeout(focus,180);window.addEventListener('petday:focus',focus);return ()=>{clearTimeout(id);window.removeEventListener('petday:focus',focus)};},[view,user,bookings,consultations,reschedules]);
 const todayLocal=(()=>{const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)})();
 const isOverdue=(b:Booking)=>Boolean(b.date&&b.date<todayLocal&&['Đang chờ xác nhận','Đã xác nhận'].includes(b.status));
 const bookingStats={today:bookings.filter(b=>b.date===todayLocal&&b.status!=='Đã hủy').length,upcoming:bookings.filter(b=>b.date>=todayLocal&&['Đang chờ xác nhận','Đã xác nhận','Đang thực hiện'].includes(b.status)).length,overdue:bookings.filter(isOverdue).length,all:bookings.length,pending:bookings.filter(b=>b.status==='Đang chờ xác nhận').length,active:bookings.filter(b=>['Đã xác nhận','Đang thực hiện'].includes(b.status)).length,done:bookings.filter(b=>b.status==='Hoàn tất').length,unpaid:bookings.filter(b=>b.paymentStatus!=='Đã thanh toán'&&b.status!=='Đã hủy').length};
 const visibleBookings=bookings.filter(b=>{
  const q=bookingSearch.trim().toLocaleLowerCase('vi-VN');
  const matches=!q||[b.code,b.petName,b.ownerName,b.service,b.branch,b.assignedStaff||''].some(x=>String(x||'').toLocaleLowerCase('vi-VN').includes(q));
  const matchesStatus=bookingFilter==='all'||(bookingFilter==='pending'&&b.status==='Đang chờ xác nhận')||(bookingFilter==='active'&&['Đã xác nhận','Đang thực hiện'].includes(b.status))||(bookingFilter==='done'&&b.status==='Hoàn tất')||(bookingFilter==='today'&&b.date===todayLocal&&b.status!=='Đã hủy')||(bookingFilter==='upcoming'&&b.date>=todayLocal&&['Đang chờ xác nhận','Đã xác nhận','Đang thực hiện'].includes(b.status))||(bookingFilter==='unpaid'&&b.paymentStatus!=='Đã thanh toán'&&b.status!=='Đã hủy')||(bookingFilter==='overdue'&&isOverdue(b));
  return matches&&matchesStatus&&matchesBookingFilters(b,{branch:filterBranch,start:filterStart,end:filterEnd});
 }).sort((a,b)=>{
  const time=(x:Booking)=>`${x.date||''}T${x.slot||'00:00'}`;
  return bookingOrder==='newest'?time(b).localeCompare(time(a)):time(a).localeCompare(time(b));
 });
 const selectedPet=pets.find(p=>p.id===petId);
